"""Residents survey crosstabs: python3 crosstabs.py INPUT_DIR OUTPUT_FILE"""
import csv
import io
import json
import os
import sys
from datetime import datetime, timedelta, timezone


def load_json(path):
    with open(path, encoding="utf-8-sig") as f:
        return json.load(f)


def read_export(path):
    with open(path, "rb") as f:
        text = f.read().decode("utf-8-sig")
    nl = text.find("\n")
    header_line = text if nl < 0 else text[:nl]
    header_line = header_line.rstrip("\r")
    delim = ","
    for d in (",", ";", "\t"):
        if d in header_line:
            delim = d
            break
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delim, quotechar='"')
    header = None
    rows = []
    for cells in reader:
        cells = [c.strip() for c in cells]
        if header is None:
            if not any(cells):
                continue
            header = cells
            continue
        if not any(cells):
            continue
        row = {}
        for i, name in enumerate(header):
            if name not in row or (i < len(cells) and cells[i] != ""):
                row[name] = cells[i] if i < len(cells) else ""
        rows.append(row)
    return rows


def parse_offset(s):
    sign = -1 if s[0] == "-" else 1
    h, m = s[1:].split(":")[:2]
    return sign * (int(h) * 60 + int(m))


def parse_time(s, meta):
    if meta.get("submitted_format") == "local":
        dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        off = parse_offset(meta.get("utc_offset", "+00:00"))
        return dt - timedelta(minutes=off)
    t = s.replace(" ", "T") if "T" not in s else s
    if t.endswith("Z") or t.endswith("z"):
        t = t[:-1] + "+00:00"
    dt = datetime.fromisoformat(t)
    if dt.tzinfo is None:
        return dt
    return dt.astimezone(timezone.utc).replace(tzinfo=None)


def parse_duration(s, meta):
    if meta.get("duration_format") == "clock":
        parts = [int(p) for p in s.split(":")]
        t = 0
        for p in parts:
            t = t * 60 + p
        return t
    return int(float(s))


def to_int(s, default=0):
    try:
        return int(s)
    except (TypeError, ValueError):
        try:
            return int(float(s))
        except (TypeError, ValueError):
            return default


def median(vals):
    v = sorted(vals)
    n = len(v)
    if n % 2:
        return v[n // 2]
    return (v[n // 2 - 1] + v[n // 2]) / 2


def apply_recode(entry, value):
    rc = entry.get("recode")
    if rc is not None:
        return rc[value]
    return to_int(value)


