    t = q["type"]
    if t == "age":
        v = row.get(entry["column"], "")
        if v == "":
            return None
        src = entry.get("source")
        if src == "band":
            code = apply_recode(entry, v)
            return None if code is None else int(code)
        age = to_int(v)
        if src == "birth_year":
            age = birth_ref_year - age
        for b in q["bands"]:
            if b["min"] <= age <= b["max"]:
                return b["code"]
