            complete = row.get(m["status"], "") == m["complete"]
            sub = row.get(m["submitted"], "")
            recs.append(dict(
                v=v, row=row, id=row.get(m["id"], ""), complete=complete,
                time=parse_time(sub, m) if sub else datetime.min,
                dur=parse_duration(row[m["duration"]], m) if row.get(m["duration"], "") != "" else None,
                page=to_int(row.get(m["last_page"], ""), 0)))

    # 1 duplicates
    best = {}
    for r in recs:
        b = best.get(r["id"])
        if b is None or (r["complete"], r["time"]) > (b["complete"], b["time"]):
            if b is not None:
                counts[b["v"]]["duplicates"] += 1
