    for v in vkeys:
        d = [r["dur"] for r in k2 if r["v"] == v and r["complete"] and r["dur"] is not None]
        if d:
            med[v] = median(d)
    k3 = []
    for r in k2:
        if r["complete"] and r["v"] in med and r["dur"] is not None and r["dur"] * 5 < med[r["v"]] * 2:
            counts[r["v"]]["speeders"] += 1
        else:
            k3.append(r)
    for r in k3:
        counts[r["v"]]["complete" if r["complete"] else "partial"] += 1

