    for r in k3:
        ans = {}
        for q in questions:
            ent = q["versions"].get(r["v"])
            if ent is None:
                continue
            if not (r["complete"] or ent["page"] <= r["page"]):
                continue
            ai = q.get("ask_if")
            if ai:
                a = ans.get(ai["question"])
                if a is None:
                    continue
                codes = set(ai["codes"])
                if isinstance(a, frozenset):
                    if not (a & codes):
                        continue
                elif a not in codes:
                    continue
            ans[q["id"]] = read_answer(q, ent, r["row"], ref_year)
            if ans[q["id"]] is None:
                ans.pop(q["id"])
                r.setdefault("asked", set()).add(q["id"])
            else:
                r.setdefault("asked", set()).add(q["id"])
        r["ans"] = ans

    n = len(k3)
    # weighting
    w = [1.0] * n
    dims = []
    for d in wt["dimensions"]:
        qid = d["question"]
        present = {r["ans"].get(qid) for r in k3}
        tg = {int(c): float(x) for c, x in d["targets"].items() if int(c) in present}
        tot = sum(tg.values())
        if not tg or tot <= 0:
            continue
        shares = {c: x / tot for c, x in tg.items()}
        cat = [r["ans"].get(qid) if r["ans"].get(qid) in shares else None for r in k3]
        dims.append((shares, cat))
    for _ in range(wt.get("max_iterations", 100)):
        done = True
        for shares, cat in dims:
            T = sum(w[i] for i in range(n) if cat[i] is not None)
            W = {c: 0.0 for c in shares}
            for i in range(n):
                if cat[i] is not None:
                    W[cat[i]] += w[i]
            f = {}
            for c in shares:
                f[c] = shares[c] * T / W[c] if W[c] > 0 else 1.0
                if abs(f[c] - 1) > wt.get("tolerance", 1e-10):
                    done = False
            for i in range(n):
                if cat[i] is not None:
                    w[i] *= f[cat[i]]
