        for cid, bq, code in cols:
            mem = [i for i in idx if bq is None or k3[i]["ans"].get(bq) == code]
            base = len(mem)
            wb = sum(w[i] for i in mem)
            vals = {}

            def has(i, codes):
                a = k3[i]["ans"][q["id"]]
                if isinstance(a, frozenset):
