                vals[net["id"]] = pct(net["codes"])
            if t.get("mean"):
                if base == 0 or wb == 0:
                    vals["mean"] = None
                else:
                    vals["mean"] = r2(sum(w[i] * score[k3[i]["ans"][q["id"]]] for i in mem) / wb)
            out_cols.append({"column": cid, "base": base, "weighted_base": r2(wb) if base else 0,
                             "values": vals})
        tables.append({"table": t["id"], "columns": out_cols})

