            out_cols.append({"column": cid, "base": base, "weighted_base": r2(wb) if base else 0,
                             "values": vals})
        tables.append({"table": t["id"], "columns": out_cols})

    with open(outfile, "w", encoding="utf-8") as f:
        json.dump({"survey": cb["survey"], "summary": summary, "tables": tables}, f, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
